+import crypto from 'node:crypto';
+import events from './events.json' with {type:'json'};
+
+const DEFAULT_PAGE_SIZE = 2;
+const MIN_PAGE_SIZE = 1;
+const MAX_PAGE_SIZE = 3;
+const CURSOR_SECRET = 'event-pagination-secret-v1';
+
+function signOffset(offset) {
+  return crypto.createHmac('sha256', CURSOR_SECRET).update(String(offset)).digest('hex');
+}
+
+function encodeCursor(offset) {
+  const payload = JSON.stringify({ o: offset, s: signOffset(offset) });
+  return Buffer.from(payload, 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  let parsed;
+  try {
+    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
+    throw new Error('Unknown cursor');
+  }
+  if (typeof parsed.o !== 'number' || !Number.isInteger(parsed.o) ||
+      parsed.o < 0 || parsed.o >= events.length) {
+    throw new Error('Unknown cursor');
+  }
+  if (typeof parsed.s !== 'string' || parsed.s !== signOffset(parsed.o)) {
+    throw new Error('Unknown cursor');
+  }
+  return parsed.o;
+}
+
+export async function listTools() {
+  return [{
+    name: 'events_list',
+    description: 'List events page by page in source order. Pass the returned next_cursor to fetch the next page.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        cursor: { type: 'string', description: 'Opaque cursor returned from a previous call.' },
+        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
+      },
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'events_list') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (key !== 'cursor' && key !== 'page_size') {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+
+  let offset = 0;
+  if (args.cursor !== undefined) {
+    if (typeof args.cursor !== 'string') {
+      throw new Error('cursor must be a string');
+    }
+    offset = decodeCursor(args.cursor);
+  }
+
+  let pageSize = DEFAULT_PAGE_SIZE;
+  if (args.page_size !== undefined) {
+    if (typeof args.page_size !== 'number' || !Number.isInteger(args.page_size) ||
+        args.page_size < MIN_PAGE_SIZE || args.page_size > MAX_PAGE_SIZE) {
+      throw new Error('page_size must be an integer between 1 and 3');
+    }
+    pageSize = args.page_size;
+  }
+
+  const page = events.slice(offset, offset + pageSize);
+  const nextOffset = offset + pageSize;
+  const result = { events: page };
+  if (nextOffset < events.length) {
+    result.next_cursor = encodeCursor(nextOffset);
+  }
+
+  return {
+    content: [{ type: 'text', text: JSON.stringify(result) }]
+  };
+}
